//! End-to-end behavior of the protocol: every test feeds command lines to `miniq::run` and
//! compares the response lines.

use std::io::Cursor;

use serde_json::{Value, json};

fn run_bytes(input: &[u8]) -> Vec<Value> {
    let mut output = Vec::new();
    miniq::run(Cursor::new(input), &mut output).expect("in-memory I/O does not fail");
    String::from_utf8(output)
        .expect("responses are UTF-8")
        .lines()
        .map(|line| serde_json::from_str(line).expect("every response line is JSON"))
        .collect()
}

fn session(commands: &[Value]) -> Vec<Value> {
    let input: String = commands.iter().map(|c| format!("{c}\n")).collect();
    let responses = run_bytes(input.as_bytes());
    assert_eq!(responses.len(), commands.len(), "one response per line");
    responses
}

fn ok() -> Value {
    json!({"ok": true})
}

fn code(response: &Value) -> &str {
    assert_eq!(response["ok"], json!(false), "{response}");
    response["error"]["code"].as_str().expect("error code is a string")
}

fn create(name: &str, attributes: Value) -> Value {
    json!({"Command": "CreateQueue", "QueueName": name, "Attributes": attributes})
}

fn send(queue: &str, body: &str) -> Value {
    json!({"Command": "SendMessage", "QueueName": queue, "Body": body})
}

fn receive(queue: &str) -> Value {
    json!({"Command": "ReceiveMessage", "QueueName": queue, "MaxMessages": 10})
}

fn tick(seconds: u64) -> Value {
    json!({"Command": "Tick", "Seconds": seconds})
}

fn attributes(queue: &str) -> Value {
    json!({"Command": "GetQueueAttributes", "QueueName": queue})
}

fn message(id: u64, handle: u64, body: &str, receive_count: u64, sent_at: u64, first: u64) -> Value {
    json!({
        "MessageId": format!("m-{id}"), "ReceiptHandle": format!("r-{handle}"), "Body": body,
        "ReceiveCount": receive_count, "SentAt": sent_at, "FirstReceivedAt": first,
    })
}

fn fifo_message(base: Value, group: &str, sequence: u64) -> Value {
    let mut base = base;
    base["GroupId"] = json!(group);
    base["SequenceNumber"] = json!(sequence);
    base
}

fn messages(list: Vec<Value>) -> Value {
    json!({"ok": true, "Messages": list})
}

#[test]
fn every_line_gets_one_response_and_bad_lines_do_not_stop_the_session() {
    let input: &[u8] = b"\n{\"Command\":\"Tick\",\"Seconds\":1}\nnot json\n[]\n{\"Command\":5}\n{\"Command\":\"Nope\"}\n{\"Command\":\"Tick\",\"Seconds\":1}";
    let responses = run_bytes(input);
    let codes: Vec<&str> = responses
        .iter()
        .map(|r| if r["ok"] == json!(true) { "ok" } else { code(r) })
        .collect();
    assert_eq!(
        codes,
        ["InvalidRequest", "ok", "InvalidRequest", "InvalidRequest", "InvalidRequest", "InvalidRequest", "ok"]
    );
    assert_eq!(responses[6], json!({"ok": true, "Now": 2}));
}

#[test]
fn invalid_utf8_is_an_invalid_request() {
    let responses = run_bytes(b"{\"Command\":\"Tick\",\"Seconds\":1,\"x\":\"\xff\"}\n");
    assert_eq!(code(&responses[0]), "InvalidRequest");
}

#[test]
fn empty_input_produces_no_output_and_a_blank_last_line_is_not_a_command() {
    assert_eq!(run_bytes(b""), Vec::<Value>::new());
    assert_eq!(run_bytes(b"\n").len(), 1);
}

#[test]
fn error_codes_follow_the_checking_order() {
    let cases: Vec<(&str, Value, &str)> = vec![
        ("missing before invalid", json!({"Command": "SendMessage", "QueueName": 5}), "MissingParameter"),
        ("null is absent", json!({"Command": "SendMessage", "QueueName": "q", "Body": null}), "MissingParameter"),
        ("wrong type", json!({"Command": "SendMessage", "QueueName": 5, "Body": "x"}), "InvalidParameterValue"),
        ("value before lookup", json!({"Command": "SendMessage", "QueueName": "nope", "Body": ""}), "InvalidParameterValue"),
        ("lookup", json!({"Command": "SendMessage", "QueueName": "nope", "Body": "x"}), "QueueDoesNotExist"),
        ("lookup of the empty name", attributes(""), "QueueDoesNotExist"),
        ("name checked first", create("bad name", json!(5)), "QueueNameInvalid"),
        ("attributes not an object", create("ok", json!(5)), "InvalidParameterValue"),
        ("suffix without Fifo", create("a.fifo", json!({})), "QueueNameInvalid"),
        ("Fifo without suffix", create("a", json!({"Fifo": true})), "QueueNameInvalid"),
        ("cbd on standard", create("a", json!({"ContentBasedDeduplication": true})), "InvalidParameterValue"),
        ("unknown attribute", create("a", json!({"Colour": 1})), "InvalidParameterValue"),
        ("attribute out of range", create("a", json!({"RetentionSeconds": 59})), "InvalidParameterValue"),
        ("lone dead-letter queue", create("a", json!({"DeadLetterQueue": "q"})), "InvalidParameterValue"),
        ("missing dead-letter queue", create("a", json!({"DeadLetterQueue": "zz", "MaxReceiveCount": 1})), "QueueDoesNotExist"),
        ("fifo dead-letter mismatch", create("a", json!({"DeadLetterQueue": "q", "MaxReceiveCount": 1, "Fifo": true})), "QueueNameInvalid"),
        ("tick float", json!({"Command": "Tick", "Seconds": 30.0}), "InvalidParameterValue"),
        ("tick exponent", json!({"Command": "Tick", "Seconds": 1e1}), "InvalidParameterValue"),
        ("tick string", json!({"Command": "Tick", "Seconds": "30"}), "InvalidParameterValue"),
        ("tick negative", json!({"Command": "Tick", "Seconds": -1}), "InvalidParameterValue"),
        ("tick too large", json!({"Command": "Tick", "Seconds": 1209601}), "InvalidParameterValue"),
        ("tick missing", json!({"Command": "Tick"}), "MissingParameter"),
        ("set without attributes", json!({"Command": "SetQueueAttributes", "QueueName": "q"}), "MissingParameter"),
        ("set Fifo", json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"Fifo": false}}), "UnsupportedOperation"),
        ("set cbd on standard", json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"ContentBasedDeduplication": true}}), "InvalidParameterValue"),
        ("set own dead-letter", json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"DeadLetterQueue": "q", "MaxReceiveCount": 1}}), "InvalidParameterValue"),
        ("set missing dead-letter", json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"DeadLetterQueue": "zz", "MaxReceiveCount": 1}}), "QueueDoesNotExist"),
        ("set mismatched dead-letter", json!({"Command": "SetQueueAttributes", "QueueName": "q", "Attributes": {"DeadLetterQueue": "f.fifo", "MaxReceiveCount": 1}}), "InvalidParameterValue"),
        ("standard send with group", json!({"Command": "SendMessage", "QueueName": "q", "Body": "x", "GroupId": "g"}), "UnsupportedOperation"),
        ("fifo send with delay", json!({"Command": "SendMessage", "QueueName": "f.fifo", "Body": "x", "DelaySeconds": 0}), "UnsupportedOperation"),
        ("fifo send without group", json!({"Command": "SendMessage", "QueueName": "f.fifo", "Body": "x"}), "MissingParameter"),
        ("fifo send without dedup id", json!({"Command": "SendMessage", "QueueName": "f.fifo", "Body": "x", "GroupId": "g"}), "MissingParameter"),
        ("bad group characters", json!({"Command": "SendMessage", "QueueName": "f.fifo", "Body": "x", "GroupId": "g g"}), "InvalidParameterValue"),
        ("receive too many", json!({"Command": "ReceiveMessage", "QueueName": "q", "MaxMessages": 11}), "InvalidParameterValue"),
        ("delete with unissued handle", json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-1"}), "ReceiptHandleInvalid"),
    ];
    let mut commands = vec![create("q", json!({})), create("f.fifo", json!({"Fifo": true}))];
    commands.extend(cases.iter().map(|(_, command, _)| command.clone()));
    let responses = session(&commands);
    for ((name, _, expected), response) in cases.iter().zip(&responses[2..]) {
        assert_eq!(code(response), *expected, "{name}: {response}");
    }
}

